import json

with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

print('=== CHANGES ===')
changes = False
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, 'MISSING')
    av = a.get(k, 'MISSING')
    if bv != av:
        changes = True
        print(f'{k[0]:15s} | {k[1]:8s} | {k[2]:45s} | {bv:10s} -> {av}')

if not changes:
    print('(none)')

print()
print('=== UNCHANGED ===')
for k in sorted(b.keys()):
    if b[k] == a.get(k):
        print(f'{k[0]:15s} | {k[1]:8s} | {k[2]:45s} | {b[k]}')
"

